import sys
sys.path.insert(0, 'src')
from marshmallow import Schema, fields, validates_schema, validates, ValidationError, pre_load, post_load
from collections import OrderedDict
import warnings

print("=== m1 Verification ===")
# Test ordered=True emits UserWarning with 'ordered' and 'dict_class'
with warnings.catch_warnings(record=True) as w:
    warnings.simplefilter("always")
    class OrderedSchema(Schema):
        name = fields.Str()
        class Meta:
            ordered = True

    user_warnings = [x for x in w if issubclass(x.category, UserWarning)]
    assert len(user_warnings) == 1
    msg = str(user_warnings[0].message)
    assert 'ordered' in msg.lower()
    assert 'dict_class' in msg
    print(f"  Warning message: {msg}")

# Test dict_class defaults to dict
class DefaultSchema(Schema):
    name = fields.Str()
s = DefaultSchema()
assert s.dump({"name": "test"}) == {"name": "test"}
print("  dict_class defaults to dict: OK")

# Test overriding dict_class returns OrderedDict
class OverrideDictClassSchema(Schema):
    name = fields.Str()
    @property
    def dict_class(self):
        return OrderedDict
s = OverrideDictClassSchema()
result = s.dump({"name": "test"})
assert isinstance(result, OrderedDict)
print("  dict_class override returns OrderedDict: OK")

