# Test data_key remapping in validators
class ApiKeySchema(Schema):
    ip_addresses = fields.String(data_key='ipAddresses')

    @validates_schema
    def validate_ip(self, data, **kwargs):
        raise ValidationError('err', field_name='ip_addresses')

try:
    ApiKeySchema().load({'ipAddresses': 'x'})
except ValidationError as e:
    assert 'ipAddresses' in e.messages
    print(f"  load() error key: {list(e.messages.keys())}")

errors = ApiKeySchema().validate({'ipAddresses': 'x'})
assert 'ipAddresses' in errors
print(f"  validate() error key: {list(errors.keys())}")

