    @validates('ip_addresses')
    def validate_ip(self, value, **kwargs):
        raise ValidationError('field err')

try:
    FieldValidatorSchema().load({'ipAddresses': 'x'})
except ValidationError as e:
    assert 'ipAddresses' in e.messages
    print(f"  @validates error key: {list(e.messages.keys())}")

