class AppendSchema(Schema):
    name = fields.Str(required=True)

    @pre_load(pass_many=True)
    def append_item(self, data, many, **kwargs):
        if many and isinstance(data, list):
            data.append({"name": "appended"})
        return data

    @post_load(pass_original=True)
    def process(self, item, original, **kwargs):
        return item

schema = AppendSchema(many=True)
result = schema.load([{"name": "item1"}, {"name": "item2"}])
assert len(result) == 3
print(f"  Result length: {len(result)} (expected 3)")
print(f"  Result: {result}")

